import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as sla
from tqdm import tqdm

def fast_eigs(A,k):
    N=A.shape[0]
    vals,vecs=sla.eigs(A,k=k,v0=np.ones(N),tol=1e-5,ncv=15,maxiter=N*40)
    return vals,vecs

def is_close(A,vals,vecs):
    # compute residual
    res=[]
    for l,v in zip(vals,vecs.T):
        resnorm=np.linalg.norm(A.dot(v)-l*v)
        res.append(resnorm/np.linalg.norm(v))
    return max(res)

n=1000; density=0.01; k=5; trials=200
fails=0; maxreslist=[]
for seed in tqdm(range(trials)):
    rng=np.random.default_rng(seed)
    A=sp.random(n,n,density=density,format='csr',data_rvs=rng.standard_normal)
    try:
        vals_f,vecs_f=fast_eigs(A,k)
    except Exception as e:
        fails+=1
        continue
    maxres=is_close(A,vals_f,vecs_f)
    maxreslist.append(maxres)
    if maxres>1e-5:
        fails+=1
print('fail',fails,' maxres max',max(maxreslist))
