import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as sla

def try_params(tol,ncv,maxiter_factor=200,seeds=100):
    fails=0
    n=1000; k=5; density=0.01
    for seed in range(seeds):
        rng=np.random.default_rng(seed)
        A=sp.random(n,n,density=density,format='csr',data_rvs=rng.standard_normal)
        v0=np.ones(n)
        try:
            vals,vecs=sla.eigs(A,k=k,v0=v0,ncv=ncv,maxiter=n*maxiter_factor,tol=tol)
        except Exception:
            fails+=1
            continue
        vals_ref,vecs_ref=sla.eigs(A,k=k,v0=v0,ncv=max(2*k+1,20),maxiter=n*200,tol=0)
        idx_ref=np.argsort(-np.abs(vals_ref)); idx=np.argsort(-np.abs(vals))
        vecs_ref=vecs_ref[:,idx_ref]; vecs=vecs[:,idx]
        # orientation maybe sign/complex factor difference; compute absolute dot product
        ok=True
        for i in range(k):
            sim=np.abs(np.vdot(vecs_ref[:,i],vecs[:,i])/(np.linalg.norm(vecs_ref[:,i])*np.linalg.norm(vecs[:,i])))
            if not np.isclose(sim,1.0,atol=1e-6):
                ok=False; break
        if not ok:
            fails+=1
    return fails
for tol in [0,1e-6,1e-7,1e-5]:
    print('tol',tol,'fails',try_params(tol=tol,ncv=20,maxiter_factor=40,seeds=50))
