from reference import Task

def test_params(tol, maxiter_factor, ncv):
    task=Task()
    fails=0; total_time=0; seeds=random.sample(range(1000000),200)
    for seed in seeds:
        prob=task.generate_problem(n=300, random_seed=seed)
        A=prob['matrix']; k=prob['k']; N=A.shape[0]
        start=time.time()
        try:
            vals,vecs=sla.eigs(A,k=k,v0=np.ones(N),ncv=ncv,maxiter=N*maxiter_factor,tol=tol)
        except Exception as e:
            fails+=1; continue
        total_time+=time.time()-start
        pairs=sorted(zip(vals,vecs.T), key=lambda p: -abs(p[0]))
        sol=[vec for _,vec in pairs]
        if not task.is_solution(prob, sol):
            fails+=1
    avg_time = total_time/(len(seeds)-fails) if (len(seeds)-fails)>0 else None
    return fails, total_time, avg_time

for ncv in [15,18,20]:
